// Editor recipes share the native event compiler; no duplicate receipt scripts.
const RECIPES={hiddenItem:{name:'Hidden item',hint:'Invisible tile interaction, receipt and saved completion',once:true,blocksMovement:false,steps:[{type:'item',operation:'give',itemId:13,quantity:1,notify:true}]},lockedDoor:{name:'Key-locked door',hint:'Choose a required key and arrival tile; keeps the key',steps:[{type:'condition',kind:'item',itemId:13,quantity:1,failText:'The door is locked. You need the right key.'},{type:'say',text:'The key unlocks the door.'},{type:'warp',to:null}]},tollPassage:{name:'Toll passage',hint:'Ask, check payment, then travel to a chosen tile',steps:[{type:'choice',text:'Pay 100 to pass?'},{type:'money',operation:'take',amount:100},{type:'warp',to:null}]},dialogue:{name:'Talk / sign',hint:'Write a conversation',steps:[{type:'say',text:'Hello there!'}]},pickup:{name:'Item pickup',hint:'Receipt, fanfare and saved completion',once:true,steps:[{type:'item',operation:'give',itemId:13,quantity:1,notify:true}]},gift:{name:'Item gift',hint:'Ask, give, remember',once:true,steps:[{type:'choice',text:'Would you like a POTION?'},{type:'item',operation:'give',itemId:13,quantity:1,notify:true}]},healer:{name:'Healer',hint:'Restore the whole party',steps:[{type:'say',text:'Let me heal your Pokémon.'},{type:'heal'},{type:'say',text:'Your Pokémon are ready!'}]},shop:{name:'Shopkeeper',hint:'Choose a named stock list',steps:[{type:'say',text:'Welcome! What do you need?'},{type:'shop',items:[13,4,14]}]},battle:{name:'Trainer battle',hint:'Choose a native trainer team',steps:[{type:'battle',trainerId:1,intro:'Let us battle!',defeat:'Well fought!'}]},pokemon:{name:'Pokémon gift',hint:'Species, level and held item',once:true,steps:[{type:'choice',text:'Will you look after this Pokémon?'},{type:'giveMon',species:25,level:5,itemId:0},{type:'say',text:'Take good care of your new friend!'}]},quest:{name:'Item exchange / quest',hint:'Requirement, reward, remember',once:true,steps:[{type:'condition',kind:'item',itemId:13,quantity:1,failText:'Bring me a POTION, please.'},{type:'item',operation:'give',itemId:4,quantity:1},{type:'item',operation:'take',itemId:13,quantity:1},{type:'say',text:'Thank you! Here is your reward.'}]},cutscene:{name:'Short cutscene',hint:'Sound, movement and dialogue',steps:[{type:'sound',soundId:5},{type:'wait',frames:30},{type:'say',text:'Did you hear that?'}]}};
export function eventRecipes(){return structuredClone(RECIPES);}
export function eventRecipe(id){if(!Object.hasOwn(RECIPES,id))throw Error('Unknown event recipe.');const r=structuredClone(RECIPES[id]);return{title:r.name,runtime:{action:'sequence',trigger:'interact',enabled:true,blocksMovement:r.blocksMovement!==false,once:!!r.once,steps:r.steps}};}
